const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();

const safeArray = (val) => Array.isArray(val) ? val : [];

const commits = safeArray($input.all()[0].json);
const issues = safeArray($input.all()[1].json);
const prs = safeArray($input.all()[2].json);

const repo = $json.repo || 'owner/repo';
const language = $json.language || 'EN';

const commitList = commits.map(c => {
  const msg = (c.commit?.message || '').split('\n')[0];
  const author = c.commit?.author?.name || c.author?.login || 'unknown';
  return `- ${msg} (${author})`;
}).join('\n');

const issueList = issues
  .filter(i => !i.pull_request)
  .filter(i => new Date(i.closed_at || 0) >= new Date(weekAgo))
  .map(i => `- #${i.number}: ${i.title}`)
  .join('\n');

const mergedPrs = prs.filter(p => p.merged_at && new Date(p.merged_at) >= new Date(weekAgo));
const prList = mergedPrs
  .map(p => `- #${p.number}: ${p.title} (${p.user?.login || 'unknown'})`)
  .join('\n');

const totalAdditions = mergedPrs.reduce((a, p) => a + (p.additions || 0), 0);
const totalDeletions = mergedPrs.reduce((a, p) => a + (p.deletions || 0), 0);

const weekStart = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
const weekEnd = new Date().toISOString().split('T')[0];

return [{
  repo,
  language,
  commits: commits.length,
  commitAuthors: [...new Set(commits.map(c => c.commit?.author?.name || c.author?.login))].filter(Boolean).length,
  issuesClosed: issues.filter(i => !i.pull_request && new Date(i.closed_at || 0) >= new Date(weekAgo)).length,
  prsMerged: mergedPrs.length,
  linesAdded: totalAdditions,
  linesRemoved: totalDeletions,
  commitDetails: commitList || 'None',
  issueDetails: issueList || 'None',
  prDetails: prList || 'None',
  weekStart: weekStart,
  weekEnd: weekEnd
}];

