const response = $input.first().json;
const repo = $input.first().context.$node['Set Variables'].json.repo;
const weekStart = $input.first().context.$node['Aggregate Data'].json.weekStart;
const weekEnd = $input.first().context.$node['Aggregate Data'].json.weekEnd;

let summary = 'No summary generated.';
if (response.content && response.content.length > 0) {
  summary = response.content[0].text;
}

const truncatedSummary = summary.length > 2048 ? summary.substring(0, 2045) + '...' : summary;

const webhookUrl = $input.first().context.$node['Set Variables'].json.discordWebhook;

if (!webhookUrl) {
  return [{
    _summary: truncatedSummary,
    _warning: 'No Discord webhook URL configured. Copy the summary from above.'
  }];
}

return [{
  webhookUrl: webhookUrl,
  content: {
    embeds: [{
      title: `Weekly Dev Summary — ${repo}`,
      description: `Week of ${weekStart} – ${weekEnd}`,
      color: 3447003,
      fields: [{
        name: 'Summary',
        value: truncatedSummary,
        inline: false
      }],
      footer: { text: 'Generated by n8n + Claude API' },
      timestamp: new Date().toISOString()
    }]
  }
}];
